// Secure: Validate and sanitize input before using it in URL construction
public class GoodExample {
    public static void main(String[] args) {
        String userInput = "http://internal-service:8080/admin"; // Malicious input
        try {
            // Validate the URL scheme and host
            if (isValidUrl(userInput)) {
                java.net.URL url = new java.net.URL(userInput);
                java.net.HttpURLConnection connection = (java.net.HttpURLConnection) url.openConnection();
                connection.setRequestMethod("GET");
                int responseCode = connection.getResponseCode();
                System.out.println("Response Code: " + responseCode);
            } else {
                System.out.println("Invalid or unsafe URL.");
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    // Helper method to validate URL
    private static boolean isValidUrl(String url) {
        try {
            java.net.URL u = new java.net.URL(url);
            // Allow only HTTP and HTTPS protocols
            if (!u.getProtocol().equals("http") && !u.getProtocol().equals("https")) {
                return false;
            }
            // Block internal hosts (example: internal-service)
            String host = u.getHost();
            if (host.contains("internal") || host.contains("localhost")) {
                return false;
            }
            return true;
        } catch (java.net.MalformedURLException e) {
            return false;
        }
    }
}
